def fn(*args, **p):
    import torch
    cpg, groups, k = p['cpg'], p['groups'], p['k']
    w = None
    for a in args:
        if torch.is_tensor(a) and a.dim() == 3 and tuple(a.shape) == (groups * cpg, cpg, k):
            w = a
            break
    if w is None:
        w = args[-1]
    W = torch.zeros(cpg * k + 1, groups * cpg, dtype=w.dtype, device=w.device)
